/// The bytes do not decode as the expected value (always a corrupt artifact).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct Malformed;

/// An append-only byte sink: the whole encoding in `bytes`, or with a `sink`, handed to it a
/// chunk at a time (`bytes` holding at most [`CHUNK`] bytes not yet handed over).
#[derive(Default)]
pub(crate) struct Writer<'a> {
    pub(crate) bytes: Vec<u8>,
    sink: Option<&'a mut dyn FnMut(&[u8])>,
}

/// The most bytes a chunked [`Writer`] holds before handing them to its sink.
pub(crate) const CHUNK: usize = 64 * 1024;

impl<'a> Writer<'a> {
    /// A writer that hands the encoding to `sink` a chunk at a time; [`Writer::finish`] hands
    /// over the rest.
    pub(crate) fn chunked(sink: &'a mut dyn FnMut(&[u8])) -> Writer<'a> {
        Writer {
            bytes: Vec::with_capacity(CHUNK),
            sink: Some(sink),
        }
    }

    /// Hand the bytes not yet handed over to the sink.
    pub(crate) fn finish(self) {
        if let Some(sink) = self.sink {
            sink(&self.bytes);
        }
    }

    fn raw(&mut self, b: &[u8]) {
        match self.sink.as_mut() {
            Some(sink) if self.bytes.len().saturating_add(b.len()) > CHUNK => {
                sink(&self.bytes);
                self.bytes.clear();
                if b.len() >= CHUNK {
                    sink(b);
                } else {
                    self.bytes.extend_from_slice(b);
                }
            }
            _ => self.bytes.extend_from_slice(b),
        }
    }

    /// A sequence count. Every in-memory sequence this crate encodes is far below `u32::MAX`
    /// items (the budgets cap modules at `SPIRV_WORDS`); a larger one saturates, which decodes as
    /// `Malformed` because fewer items follow than the count names.
    fn count(&mut self, n: usize) {
        self.raw(&u32::try_from(n).unwrap_or(u32::MAX).to_le_bytes());
    }
}

/// A cursor over untrusted bytes.
pub(crate) struct Reader<'a> {
    bytes: &'a [u8],
}

impl<'a> Reader<'a> {
    pub(crate) fn new(bytes: &'a [u8]) -> Reader<'a> {
        Reader { bytes }
    }

    /// The bytes not yet read.
    pub(crate) fn remaining(&self) -> usize {
        self.bytes.len()
    }

    pub(crate) fn take(&mut self, n: usize) -> Result<&'a [u8], Malformed> {
        if n > self.bytes.len() {
            return Err(Malformed);
        }
        let (head, tail) = self.bytes.split_at(n);
        self.bytes = tail;
        Ok(head)
    }

    fn array<const N: usize>(&mut self) -> Result<[u8; N], Malformed> {
        let mut out = [0u8; N];
        out.copy_from_slice(self.take(N)?);
        Ok(out)
    }

    /// A sequence count of items each at least `min_item` bytes long, checked against the bytes
    /// left.
    fn count(&mut self, min_item: usize) -> Result<usize, Malformed> {
        let n = u32::from_le_bytes(self.array()?) as usize;
        if n.saturating_mul(min_item.max(1)) > self.bytes.len() {
            return Err(Malformed);
        }
        Ok(n)
    }
}

/// A value with a canonical byte encoding.
///
/// Adding a field to an encoded struct: content digests omit a field whose value is zero (its
/// encoding all zero bytes: `0`, `false`, `None`, empty), so a new field must hold its zero value
/// exactly when the artifact means what it meant before the field existed. If its zero would mean
/// new behaviour for existing pipelines, the addition must also bump the runtime version or the
/// validation executor's ABI (ask the orchestrator): the digest cannot see it (`digest`,
/// `docs/VALIDATION.md`).
pub(crate) trait Codec: Sized {
    /// The fewest bytes one encoded value takes (bounds sequence counts before reserving).
    const MIN_BYTES: usize = 1;
    /// Whether the value holds no struct or enum, so its content-digest node is the leaf of its
    /// whole encoding ([`Codec::digest`]).
    const LEAF: bool = true;
    fn put(&self, w: &mut Writer);
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed>;

    /// The value's node in a content digest: the leaf of its encoding, unless the value is or holds
    /// a struct or an enum, whose impls give their named nodes.
    fn digest(&self) -> Node {
        leaf(self)
    }

    /// The items of a sequence, one after another (a byte sequence's bytes at once).
    fn put_items(items: &[Self], w: &mut Writer) {
        for v in items {
            v.put(w);
        }
    }

    /// The `n` items of a sequence (a byte sequence's bytes at once).
    fn get_items(r: &mut Reader<'_>, n: usize) -> Result<Vec<Self>, Malformed> {
        let mut out = Vec::with_capacity(n);
        for _ in 0..n {
            out.push(Self::get(r)?);
        }
        Ok(out)
    }

    /// The `n` items of a shared sequence (a byte sequence's bytes copied once).
    fn get_shared(r: &mut Reader<'_>, n: usize) -> Result<Arc<[Self]>, Malformed> {
        Self::get_items(r, n).map(Arc::from)
    }
}

/// Encode one value.
pub(crate) fn encode<T: Codec>(v: &T) -> Vec<u8> {
    let mut w = Writer::default();
    v.put(&mut w);
    w.bytes
}

/// Encode one value into `sink`, a chunk at a time: the bytes [`encode`] gives, never held whole.
pub(crate) fn encode_chunked<T: Codec>(v: &T, sink: &mut dyn FnMut(&[u8])) {
    let mut w = Writer::chunked(sink);
    v.put(&mut w);
    w.finish();
}

/// The leaf node of `v`'s whole encoding, streamed.
fn leaf<T: Codec>(v: &T) -> Node {
    Node::leaf(|sink| encode_chunked(v, sink))
}

/// The node of a sequence `whole` of `items`: the leaf of its encoding when the items are leaves,
/// else the sequence of their nodes.
fn sequence<C: Codec, T: Codec>(whole: &C, items: &[T]) -> Node {
    if T::LEAF {
        leaf(whole)
    } else {
        Node::sequence(items.iter().map(Codec::digest))
    }
}

/// Decode one value that must use every byte.
pub(crate) fn decode<T: Codec>(bytes: &[u8]) -> Result<T, Malformed> {
    let mut r = Reader::new(bytes);
    let v = T::get(&mut r)?;
    if r.remaining() != 0 {
        return Err(Malformed);
    }
    Ok(v)
}

// ---- Primitives ----

macro_rules! codec_int {
    ($($t:ty),*) => {$(
        impl Codec for $t {
            const MIN_BYTES: usize = std::mem::size_of::<$t>();
            fn put(&self, w: &mut Writer) {
                w.raw(&self.to_le_bytes());
            }
            fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
                Ok(<$t>::from_le_bytes(r.array()?))
            }
        }
    )*};
}

codec_int!(u16, u32, u64, i32, i64);

impl Codec for u8 {
    fn put(&self, w: &mut Writer) {
        w.raw(&[*self]);
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        Ok(r.array::<1>()?[0])
    }
    fn put_items(items: &[u8], w: &mut Writer) {
        w.raw(items);
    }
    fn get_items(r: &mut Reader<'_>, n: usize) -> Result<Vec<u8>, Malformed> {
        Ok(r.take(n)?.to_vec())
    }
    fn get_shared(r: &mut Reader<'_>, n: usize) -> Result<Arc<[u8]>, Malformed> {
        Ok(Arc::from(r.take(n)?))
    }
}

impl Codec for bool {
    fn put(&self, w: &mut Writer) {
        w.raw(&[u8::from(*self)]);
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        match u8::get(r)? {
            0 => Ok(false),
            1 => Ok(true),
            _ => Err(Malformed),
        }
    }
}

/// By its bits, so every value (NaN payloads included) round-trips exactly.
impl Codec for f32 {
    const MIN_BYTES: usize = 4;
    fn put(&self, w: &mut Writer) {
        self.to_bits().put(w);
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        Ok(f32::from_bits(u32::get(r)?))
    }
}

impl Codec for String {
    const MIN_BYTES: usize = 4;
    fn put(&self, w: &mut Writer) {
        w.count(self.len());
        w.raw(self.as_bytes());
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        let n = r.count(1)?;
        let bytes = r.take(n)?;
        String::from_utf8(bytes.to_vec()).map_err(|_| Malformed)
    }
}

impl<T: Codec> Codec for Vec<T> {
    const MIN_BYTES: usize = 4;
    const LEAF: bool = T::LEAF;
    fn digest(&self) -> Node {
        sequence(self, self)
    }
    fn put(&self, w: &mut Writer) {
        w.count(self.len());
        T::put_items(self, w);
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        let n = r.count(T::MIN_BYTES)?;
        T::get_items(r, n)
    }
}

impl<T: Codec> Codec for Box<[T]> {
    const MIN_BYTES: usize = 4;
    const LEAF: bool = T::LEAF;
    fn digest(&self) -> Node {
        sequence(self, self)
    }
    fn put(&self, w: &mut Writer) {
        w.count(self.len());
        T::put_items(self, w);
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        Ok(Vec::<T>::get(r)?.into_boxed_slice())
    }
}

impl<T: Codec> Codec for Arc<[T]> {
    const MIN_BYTES: usize = 4;
    const LEAF: bool = T::LEAF;
    fn digest(&self) -> Node {
        sequence(self, self)
    }
    fn put(&self, w: &mut Writer) {
        w.count(self.len());
        T::put_items(self, w);
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        let n = r.count(T::MIN_BYTES)?;
        T::get_shared(r, n)
    }
}

impl<T: Codec> Codec for Arc<T> {
    const MIN_BYTES: usize = T::MIN_BYTES;
    const LEAF: bool = T::LEAF;
    fn digest(&self) -> Node {
        T::digest(self)
    }
    fn put(&self, w: &mut Writer) {
        T::put(self, w);
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        Ok(Arc::new(T::get(r)?))
    }
}

impl<T: Codec> Codec for Box<T> {
    const MIN_BYTES: usize = T::MIN_BYTES;
    const LEAF: bool = T::LEAF;
    fn digest(&self) -> Node {
        T::digest(self)
    }
    fn put(&self, w: &mut Writer) {
        T::put(self, w);
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        Ok(Box::new(T::get(r)?))
    }
}

impl<T: Codec> Codec for Option<T> {
    const LEAF: bool = T::LEAF;
    fn digest(&self) -> Node {
        match self {
            _ if T::LEAF => leaf(self),
            None => Node::ZERO,
            Some(v) => Node::some(v.digest()),
        }
    }
    fn put(&self, w: &mut Writer) {
        match self {
            None => false.put(w),
            Some(v) => {
                true.put(w);
                v.put(w);
            }
        }
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        if bool::get(r)? {
            Ok(Some(T::get(r)?))
        } else {
            Ok(None)
        }
    }
}

impl<A: Codec, B: Codec> Codec for (A, B) {
    const MIN_BYTES: usize = A::MIN_BYTES + B::MIN_BYTES;
    const LEAF: bool = A::LEAF && B::LEAF;
    fn digest(&self) -> Node {
        if Self::LEAF {
            leaf(self)
        } else {
            Node::tuple([self.0.digest(), self.1.digest()])
        }
    }
    fn put(&self, w: &mut Writer) {
        self.0.put(w);
        self.1.put(w);
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        Ok((A::get(r)?, B::get(r)?))
    }
}

impl<T: Codec, const N: usize> Codec for [T; N] {
    const MIN_BYTES: usize = T::MIN_BYTES * N;
    const LEAF: bool = T::LEAF;
    fn digest(&self) -> Node {
        if T::LEAF {
            leaf(self)
        } else {
            Node::tuple(self.iter().map(Codec::digest))
        }
    }
    fn put(&self, w: &mut Writer) {
        for v in self {
            v.put(w);
        }
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        let mut out = Vec::with_capacity(N);
        for _ in 0..N {
            out.push(T::get(r)?);
        }
        out.try_into().map_err(|_| Malformed)
    }
}

impl<K: Codec + Ord, V: Codec> Codec for BTreeMap<K, V> {
    const MIN_BYTES: usize = 4;
    const LEAF: bool = K::LEAF && V::LEAF;
    /// The sequence of its entries, each the pair of its key's and value's nodes.
    fn digest(&self) -> Node {
        if Self::LEAF {
            leaf(self)
        } else {
            Node::sequence(
                self.iter()
                    .map(|(k, v)| Node::tuple([k.digest(), v.digest()])),
            )
        }
    }
    fn put(&self, w: &mut Writer) {
        w.count(self.len());
        for (k, v) in self {
            k.put(w);
            v.put(w);
        }
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        let n = r.count(K::MIN_BYTES + V::MIN_BYTES)?;
        let mut out = BTreeMap::new();
        for _ in 0..n {
            let k = K::get(r)?;
            if out.last_key_value().is_some_and(|(last, _)| *last >= k) {
                return Err(Malformed);
            }
            let v = V::get(r)?;
            out.insert(k, v);
        }
        Ok(out)
    }
}

impl<T: Codec + Ord> Codec for BTreeSet<T> {
    const MIN_BYTES: usize = 4;
    const LEAF: bool = T::LEAF;
    fn digest(&self) -> Node {
        if T::LEAF {
            leaf(self)
        } else {
            Node::sequence(self.iter().map(Codec::digest))
        }
    }
    fn put(&self, w: &mut Writer) {
        w.count(self.len());
        for v in self {
            v.put(w);
        }
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        let n = r.count(T::MIN_BYTES)?;
        let mut out = BTreeSet::new();
        for _ in 0..n {
            let v = T::get(r)?;
            if out.last().is_some_and(|last| *last >= v) {
                return Err(Malformed);
            }
            out.insert(v);
        }
        Ok(out)
    }
}

/// An enum variant's name tag.
fn put_tag(w: &mut Writer, name: &str) {
    let len = u8::try_from(name.len()).unwrap_or(u8::MAX);
    w.raw(&[len]);
    w.raw(name.as_bytes());
}

fn get_tag<'a>(r: &mut Reader<'a>) -> Result<&'a [u8], Malformed> {
    let len = u8::get(r)?;
    r.take(usize::from(len))
}

// ---- Generated impls ----

/// A struct as its fields in declaration order. The pattern names every field and has no `..`,
/// so a new field fails to compile until it is added here. Its digest node names each field.
macro_rules! codec_struct {
    ($($ty:ident { $($f:ident),* $(,)? })*) => {$(
        impl Codec for $ty {
            const LEAF: bool = false;
            fn digest(&self) -> Node {
                let $ty { $($f),* } = self;
                Node::fields(&mut [$((stringify!($f), Codec::digest($f))),*])
            }
            fn put(&self, w: &mut Writer) {
                let $ty { $($f),* } = self;
                $(Codec::put($f, w);)*
            }
            fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
                $(let $f = Codec::get(r)?;)*
                Ok($ty { $($f),* })
            }
        }
    )*};
}

/// A one-field tuple struct as its field, in its encoding and its digest node.
macro_rules! codec_newtype {
    ($($ty:ident),* $(,)?) => {$(
        impl Codec for $ty {
            const LEAF: bool = false;
            fn digest(&self) -> Node {
                let $ty(v) = self;
                Codec::digest(v)
            }
            fn put(&self, w: &mut Writer) {
                let $ty(v) = self;
                Codec::put(v, w);
            }
            fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
                Ok($ty(Codec::get(r)?))
            }
        }
    )*};
}

/// An enum as its variant name, then the variant's fields. The match has no wildcard, so a new
/// variant fails to compile until it is added here. Its digest node names the variant and each
/// field: a tuple variant's fields by the names written here (`f0`, `f1`, ...).
macro_rules! codec_enum {
    ($($ty:ident {
        $($v:ident $(( $($t:ident),* ))? $({ $($f:ident),* })?),* $(,)?
    })*) => {$(
        impl Codec for $ty {
            const LEAF: bool = false;
            fn digest(&self) -> Node {
                match self {
                    $($ty::$v $(( $($t),* ))? $({ $($f),* })? => Node::variant(
                        stringify!($v),
                        &mut [
                            $($((stringify!($t), Codec::digest($t)),)*)?
                            $($((stringify!($f), Codec::digest($f)),)*)?
                        ],
                    ),)*
                }
            }
            fn put(&self, w: &mut Writer) {
                match self {
                    $($ty::$v $(( $($t),* ))? $({ $($f),* })? => {
                        put_tag(w, stringify!($v));
                        $($(Codec::put($t, w);)*)?
                        $($(Codec::put($f, w);)*)?
                    })*
                }
            }
            fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
                let tag = get_tag(r)?;
                $(if tag == stringify!($v).as_bytes() {
                    $($(let $t = Codec::get(r)?;)*)?
                    $($(let $f = Codec::get(r)?;)*)?
                    return Ok($ty::$v $(( $($t),* ))? $({ $($f),* })?);
                })*
                Err(Malformed)
            }
        }
    )*};
}

/// A registry newtype over its raw number (`vk_enum!`/`vk_flags!`: every raw value is a value).
macro_rules! codec_vk_raw {
    ($($ty:ident: $raw:ty),* $(,)?) => {$(
        impl Codec for vk::$ty {
            const MIN_BYTES: usize = std::mem::size_of::<$raw>();
            fn put(&self, w: &mut Writer) {
                self.as_raw().put(w);
            }
            fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
                Ok(vk::$ty::from_raw(<$raw>::get(r)?))
            }
        }
    )*};
}

codec_vk_raw!(
    Format: i32,
    DescriptorType: i32,
    VertexInputRate: i32,
    PrimitiveTopology: i32,
    DynamicState: i32,
    BlendFactor: i32,
    BlendOp: i32,
    LogicOp: i32,
    Filter: i32,
    SamplerMipmapMode: i32,
    SamplerAddressMode: i32,
    CompareOp: i32,
    BorderColor: i32,
    SamplerReductionMode: i32,
    ComponentSwizzle: i32,
    PipelineShaderStageCreateFlags: u32,
    DescriptorSetLayoutCreateFlags: u32,
    ShaderStageFlags: u32,
    DescriptorBindingFlags: u32,
    SampleCountFlags: u32,
    ColorComponentFlags: u32,
);

/// Exactly one named stage bit (`vk_bit!`).
impl Codec for vk::ShaderStage {
    const MIN_BYTES: usize = 4;
    fn put(&self, w: &mut Writer) {
        self.as_raw().put(w);
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        vk::ShaderStage::from_raw(u32::get(r)?).ok_or(Malformed)
    }
}

/// A Metal enum over its checked raw ordinal (`metal_enum!`).
macro_rules! codec_metal_enum {
    ($($ty:ident),* $(,)?) => {$(
        impl Codec for metal::$ty {
            const MIN_BYTES: usize = 4;
            fn put(&self, w: &mut Writer) {
                self.as_raw().put(w);
            }
            fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
                metal::$ty::try_from(u32::get(r)?).map_err(|_| Malformed)
            }
        }
    )*};
}

codec_metal_enum!(
    PixelFormat,
    BlendFactor,
    BlendOperation,
    TextureType,
    VertexFormat,
    VertexStepFunction,
    AttributeFormat,
    StepFunction,
    IndexType,
    TessellationFactorStepFunction,
    TessellationControlPointIndexType,
    TessellationPartitionMode,
    TessellationFactorFormat,
    Winding,
    DataType,
    BindingType,
    BindingAccess,
    SamplerAddressMode,
);

/// A SPIR-V capability by its grammar number; one the grammar does not name is malformed, since
/// only the builder writes these.
impl Codec for SpirvCapability {
    const MIN_BYTES: usize = 4;
    fn put(&self, w: &mut Writer) {
        self.as_raw().put(w);
    }
    fn get(r: &mut Reader<'_>) -> Result<Self, Malformed> {
        let c = SpirvCapability::from_raw(u32::get(r)?);
        c.known().map(|_| c).ok_or(Malformed)
    }
}

